window.QUESTOES = window.QUESTOES || [];
QUESTOES.push(
/* ===== CAP 12 – HEDIONDOS ===== */
{c:'c12',b:'Vunesp',e:`Nos termos da Lei nº 8.072/1990, é considerado hediondo o crime de`,
o:[`roubo simples.`,`roubo praticado com emprego de arma branca.`,`roubo circunstanciado pelo emprego de arma de fogo.`,`furto qualificado pelo rompimento de obstáculo.`,`lesão corporal grave contra pessoa comum.`],a:2,
x:`Art. 1º, II, "b": roubo com emprego de arma de fogo (ou de arma de uso proibido ou restrito). Também são hediondos o roubo com restrição de liberdade da vítima e o roubo com resultado lesão grave ou morte.`},

{c:'c12',b:'FCC',e:`Após a Lei nº 13.964/2019 (Pacote Anticrime), NÃO é considerado hediondo o crime de`,
o:[`posse ou porte ilegal de arma de fogo de uso proibido.`,`comércio ilegal de arma de fogo.`,`tráfico internacional de arma de fogo.`,`posse ou porte ilegal de arma de fogo de uso restrito.`,`organização criminosa voltada à prática de crime hediondo.`],a:3,
x:`O Pacote Anticrime restringiu a hediondez do art. 16 do Estatuto do Desarmamento à arma de uso proibido. Uso restrito deixou de ser hediondo. Comércio ilegal (art. 17) e tráfico internacional (art. 18) são hediondos.`},

{c:'c12',b:'Vunesp',e:`Nos crimes hediondos, na prática da tortura, no tráfico ilícito de entorpecentes e no terrorismo, a prisão temporária terá o prazo de`,
o:[`5 dias, prorrogável por igual período.`,`10 dias, improrrogável.`,`30 dias, prorrogável por igual período em caso de extrema e comprovada necessidade.`,`60 dias, improrrogável.`,`15 dias, prorrogável uma vez.`],a:2,
x:`Art. 2º, § 4º, da Lei 8.072/90. Nos demais crimes do rol da Lei 7.960/89, o prazo é de 5 dias, prorrogável por igual período.`},

{c:'c12',b:'FCC',e:`Os crimes hediondos, a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins e o terrorismo são, nos termos do art. 2º da Lei nº 8.072/1990, insuscetíveis de`,
o:[`anistia, graça, indulto e fiança.`,`liberdade provisória e progressão de regime.`,`anistia e graça, apenas, sendo permitidos indulto e fiança.`,`fiança e prescrição.`,`substituição por pena restritiva de direitos, em qualquer hipótese.`],a:0,
x:`Art. 2º, I e II. A CF (art. 5º, XLIII) veda fiança, graça e anistia; a lei acrescentou o indulto (o STF admite). Liberdade provisória sem fiança e progressão de regime são possíveis.`},

{c:'c12',b:'Vunesp',e:`De acordo com o entendimento do STF e com o art. 112, § 5º, da Lei de Execução Penal, o tráfico de drogas privilegiado (art. 33, § 4º, da Lei nº 11.343/2006)`,
o:[`é equiparado a hediondo.`,`não é considerado hediondo ou equiparado.`,`é hediondo apenas se praticado por reincidente.`,`é hediondo se a quantidade de droga for expressiva.`,`é crime de menor potencial ofensivo.`],a:1,
x:`STF, HC 118.533 (2016), e art. 112, § 5º, LEP (Lei 13.964/2019). A Súmula 512 do STJ, em sentido contrário, foi cancelada.`},

{c:'c12',b:'FCC',e:`Para a progressão de regime, o apenado primário condenado por crime hediondo ou equiparado, sem resultado morte, deverá ter cumprido ao menos`,
o:[`1/6 da pena.`,`2/5 (40%) da pena.`,`50% da pena.`,`60% da pena.`,`70% da pena.`],a:1,
x:`Art. 112, V, da LEP (Pacote Anticrime): 40%. Com resultado morte: 50% (vedado livramento). Reincidente em hediondo: 60%. Reincidente em hediondo com morte: 70% (vedado livramento).`},

{c:'c12',b:'Vunesp',e:`O condenado reincidente na prática de crime hediondo ou equiparado com resultado morte progredirá de regime após cumprir`,
o:[`40% da pena.`,`50% da pena.`,`60% da pena.`,`70% da pena, vedado o livramento condicional.`,`2/3 da pena, permitido o livramento condicional.`],a:3,
x:`Art. 112, VIII, da LEP.`},

{c:'c12',b:'FCC',e:`Quando a associação criminosa (art. 288 do CP) tiver por fim a prática de crimes hediondos, tortura, tráfico de drogas ou terrorismo, a pena será de reclusão de`,
o:[`1 a 3 anos.`,`2 a 4 anos.`,`3 a 6 anos, e o participante que denunciar à autoridade o bando, possibilitando seu desmantelamento, terá a pena reduzida de 1 a 2/3.`,`3 a 8 anos, sem possibilidade de redução.`,`4 a 10 anos.`],a:2,
x:`Art. 8º e parágrafo único da Lei 8.072/90 (delação premiada).`},

{c:'c12',b:'Vunesp',e:`Quanto ao critério adotado para definir os crimes hediondos, o Brasil adotou o sistema`,
o:[`judicial, cabendo ao juiz, no caso concreto, reconhecer a hediondez.`,`legal, sendo hediondos apenas os crimes taxativamente enumerados em lei, consumados ou tentados.`,`misto, em que a lei enumera exemplos e o juiz pode ampliá-los.`,`doutrinário.`,`constitucional, sendo hediondos apenas os crimes enumerados na Constituição.`],a:1,
x:`Critério legal: rol taxativo do art. 1º da Lei 8.072/90, nas formas consumada ou tentada.`},

{c:'c12',b:'FCC',e:`É hediondo, nos termos da Lei nº 8.072/1990, o furto`,
o:[`qualificado pelo abuso de confiança.`,`qualificado pelo emprego de explosivo ou de artefato análogo que cause perigo comum.`,`praticado durante o repouso noturno.`,`de veículo automotor transportado para outro Estado.`,`qualificado pelo concurso de duas ou mais pessoas.`],a:1,
x:`Art. 1º, IX (art. 155, § 4º-A, CP), incluído pelo Pacote Anticrime.`},

{c:'c12',b:'Vunesp',e:`A lesão corporal dolosa de natureza gravíssima praticada contra policial militar no exercício da função ou em decorrência dela`,
o:[`não é crime hediondo.`,`é crime hediondo, assim como a lesão corporal seguida de morte nas mesmas circunstâncias, estendendo-se a proteção ao cônjuge, companheiro ou parente consanguíneo até 3º grau, em razão dessa condição.`,`é hediondo apenas se resultar morte.`,`é hediondo apenas se praticado por organização criminosa.`,`é crime militar, insuscetível de hediondez.`],a:1,
x:`Art. 1º, I-A, da Lei 8.072/90 (Lei 13.142/2015). A lesão grave (não gravíssima) contra policial não está no rol.`},

{c:'c12',b:'FCC',e:`<p>Considere as afirmações sobre a Lei nº 8.072/1990:</p><ol type="I"><li>O STF declarou inconstitucional a imposição obrigatória de regime inicial fechado aos condenados por crime hediondo.</li><li>É vedada, em qualquer hipótese, a concessão de liberdade provisória sem fiança aos acusados de crime hediondo.</li><li>O livramento condicional exige o cumprimento de mais de 2/3 da pena, se o apenado não for reincidente específico em crimes dessa natureza.</li></ol><p>Está correto o que se afirma APENAS em</p>`,
o:[`I.`,`II.`,`I e III.`,`II e III.`,`III.`],a:2,
x:`I: HC 111.840. III: art. 83, V, CP. II errada: a vedação é à fiança; a liberdade provisória sem fiança é possível, conforme o STF.`},

{c:'c12',b:'Vunesp',e:`Com a Lei nº 14.994/2024, o feminicídio`,
o:[`deixou de ser hediondo.`,`passou a constar do rol de crimes hediondos como crime autônomo (art. 121-A do CP).`,`passou a ser equiparado a hediondo, sem integrar o rol.`,`tornou-se imprescritível.`,`passou a ser julgado pelo juiz singular.`],a:1,
x:`Art. 1º, I-B, da Lei 8.072/90. Feminicídio continua sendo crime doloso contra a vida, julgado pelo Tribunal do Júri, e não é imprescritível.`},

/* ===== CAP 13 – DROGAS ===== */
{c:'c13',b:'Vunesp',e:`Policiais militares abordam pessoa que traz consigo pequena porção de cocaína para consumo pessoal. Nos termos da Lei nº 11.343/2006,`,
o:[`deve ser lavrado auto de prisão em flagrante, com arbitramento de fiança.`,`não se imporá prisão em flagrante, devendo o autor ser encaminhado ao juízo competente ou, na falta deste, assumir o compromisso de a ele comparecer, lavrando-se termo circunstanciado.`,`o autor deve ser conduzido ao presídio até a audiência de custódia.`,`a conduta é atípica e a droga deve ser devolvida.`,`o autor deve ser autuado por tráfico, cabendo à defesa provar o consumo.`],a:1,
x:`Art. 48, § 2º. Se ausente a autoridade judicial, as providências serão tomadas pela autoridade policial, vedada a detenção do agente (§ 3º). Para drogas que não a maconha, o art. 28 continua sendo crime.`},

{c:'c13',b:'FCC',e:`Para determinar se a droga destinava-se a consumo pessoal, o juiz atenderá, nos termos do art. 28, § 2º, da Lei nº 11.343/2006,`,
o:[`exclusivamente à quantidade de droga apreendida.`,`à natureza e à quantidade da substância apreendida, ao local e às condições em que se desenvolveu a ação, às circunstâncias sociais e pessoais, bem como à conduta e aos antecedentes do agente.`,`apenas à declaração do agente e ao laudo toxicológico.`,`ao valor de mercado da droga e à renda do agente.`,`à manifestação da autoridade policial, que é vinculante.`],a:1,
x:`Literalidade do art. 28, § 2º.`},

{c:'c13',b:'Vunesp',e:`As penas de prestação de serviços à comunidade e de medida educativa de comparecimento a programa ou curso educativo, previstas no art. 28 da Lei de Drogas, serão aplicadas pelo prazo máximo de`,
o:[`3 meses, e de 6 meses em caso de reincidência.`,`5 meses, e de 10 meses em caso de reincidência.`,`6 meses, e de 1 ano em caso de reincidência.`,`1 ano, e de 2 anos em caso de reincidência.`,`10 meses, e de 20 meses em caso de reincidência.`],a:1,
x:`Art. 28, §§ 3º e 4º. Para garantir o cumprimento, o juiz pode aplicar sucessivamente admoestação verbal e multa (§ 6º). Prescrição: 2 anos (art. 30).`},

{c:'c13',b:'FCC',e:`No julgamento do RE 635.659 (Tema 506), em 2024, o STF fixou, entre outras teses, que`,
o:[`o porte de qualquer droga para consumo pessoal deixou de ser ilícito.`,`não comete infração penal quem adquire, guarda ou traz consigo cannabis sativa para consumo pessoal, presumindo-se usuário quem portar até 40 gramas ou cultivar até 6 plantas-fêmeas, presunção relativa que não impede a prisão por tráfico diante de outros elementos.`,`o porte de até 100 gramas de maconha é sempre considerado consumo pessoal, vedada a prisão em flagrante por tráfico.`,`o porte de maconha para consumo pessoal é crime punido com detenção.`,`a polícia não pode apreender a maconha encontrada com o usuário.`],a:1,
x:`Tema 506: para a maconha, a conduta do art. 28 é ilícito extrapenal (apreensão da droga, advertência e medida educativa, sem efeitos penais). Presunção relativa: elementos como balança, embalagens, registros de venda e diversidade de drogas autorizam a prisão por tráfico, mesmo abaixo de 40 g, com justificação.`},

{c:'c13',b:'Vunesp',e:`Oferecer droga, eventualmente e sem objetivo de lucro, a pessoa de seu relacionamento, para juntos a consumirem, configura`,
o:[`tráfico de drogas, com pena de 5 a 15 anos.`,`o crime do art. 33, § 3º, da Lei nº 11.343/2006, punido com detenção de 6 meses a 1 ano e multa, sem prejuízo das penas do art. 28.`,`fato atípico.`,`apenas a conduta do art. 28.`,`associação para o tráfico.`],a:1,
x:`Art. 33, § 3º (uso compartilhado). Requisitos cumulativos: eventualidade, ausência de lucro, pessoa do relacionamento e consumo conjunto. Faltando um deles, é tráfico (caput).`},

{c:'c13',b:'FCC',e:`Nos delitos do art. 33, caput e § 1º, da Lei de Drogas, as penas poderão ser reduzidas de um sexto a dois terços, desde que o agente`,
o:[`confesse espontaneamente a prática do crime.`,`seja primário, de bons antecedentes, não se dedique às atividades criminosas nem integre organização criminosa.`,`seja dependente químico.`,`tenha sido flagrado com pequena quantidade de droga, apenas.`,`seja menor de 21 anos na data do fato.`],a:1,
x:`Art. 33, § 4º (tráfico privilegiado). Requisitos cumulativos. Não é hediondo e admite substituição por restritiva de direitos.`},

{c:'c13',b:'Vunesp',e:`O crime de associação para o tráfico (art. 35 da Lei nº 11.343/2006) configura-se quando`,
o:[`três ou mais pessoas se associam para a prática reiterada do tráfico.`,`duas ou mais pessoas se associam para o fim de praticar, reiteradamente ou não, os crimes dos arts. 33, caput e § 1º, e 34, exigindo a jurisprudência estabilidade e permanência do vínculo.`,`duas pessoas praticam juntas, eventualmente, um único ato de tráfico.`,`quatro ou mais pessoas se organizam com divisão de tarefas.`,`qualquer pessoa colabora como informante.`],a:1,
x:`Art. 35: duas ou mais pessoas (a associação criminosa do CP exige três). O STJ exige vínculo estável e permanente; o mero concurso eventual não basta. A associação para o tráfico não é hedionda.`},

{c:'c13',b:'FCC',e:`Colaborar, como informante, com grupo, organização ou associação destinados à prática do tráfico de drogas é crime previsto no art. 37 da Lei nº 11.343/2006, punido com`,
o:[`reclusão, de 2 a 6 anos, e multa.`,`reclusão, de 5 a 15 anos.`,`detenção, de 6 meses a 2 anos.`,`reclusão, de 8 a 20 anos.`,`reclusão, de 3 a 10 anos.`],a:0,
x:`Art. 37 ("olheiro", "fogueteiro"). Financiar ou custear o tráfico: art. 36, reclusão de 8 a 20 anos. Associação: art. 35, reclusão de 3 a 10 anos.`},

{c:'c13',b:'Vunesp',e:`O inquérito policial relativo aos crimes da Lei de Drogas será concluído no prazo de`,
o:[`10 dias, se o indiciado estiver preso, e 30 dias, se solto.`,`30 dias, se o indiciado estiver preso, e 90 dias, se solto, podendo ser duplicados pelo juiz, ouvido o Ministério Público, mediante pedido justificado da autoridade de polícia judiciária.`,`15 dias, se preso, e 30 dias, se solto, improrrogáveis.`,`60 dias, em qualquer caso.`,`30 dias, se preso, e 60 dias, se solto, prorrogáveis uma vez pelo delegado.`],a:1,
x:`Art. 51 e parágrafo único da Lei 11.343/2006.`},

{c:'c13',b:'FCC',e:`Para efeito da lavratura do auto de prisão em flagrante e estabelecimento da materialidade do delito de tráfico, é suficiente o laudo de constatação da natureza e quantidade da droga, firmado por`,
o:[`dois peritos oficiais, obrigatoriamente.`,`perito oficial ou, na falta deste, por pessoa idônea, sendo que o perito que subscrever esse laudo não ficará impedido de participar da elaboração do laudo definitivo.`,`médico legista, apenas.`,`qualquer policial militar que participou da apreensão.`,`perito oficial, ficando ele impedido de elaborar o laudo definitivo.`],a:1,
x:`Art. 50, §§ 1º e 2º, da Lei 11.343/2006.`},

{c:'c13',b:'Vunesp',e:`Segundo a Súmula 587 do STJ, para a incidência da majorante do tráfico entre Estados da Federação (art. 40, V, da Lei de Drogas),`,
o:[`é indispensável a efetiva transposição da fronteira estadual.`,`é desnecessária a efetiva transposição de fronteiras entre estados da federação, sendo suficiente a demonstração inequívoca da intenção de realizar o tráfico interestadual.`,`exige-se que a droga seja apreendida no Estado de destino.`,`exige-se prova de que o agente reside em outro Estado.`,`a competência passa a ser da Justiça Federal.`],a:1,
x:`Súmula 587 STJ. Raciocínio semelhante vale para o tráfico transnacional (Súmula 607 STJ). Tráfico interestadual continua na Justiça Estadual; só o transnacional vai para a Justiça Federal.`},

{c:'c13',b:'FCC',e:`Segundo a jurisprudência dos Tribunais Superiores, a causa de aumento do tráfico praticado em transporte público (art. 40, III, da Lei de Drogas)`,
o:[`incide sempre que o agente utiliza transporte público para levar a droga.`,`exige que o agente comercialize ou tente comercializar a droga no interior do transporte público, não bastando o mero uso do transporte para conduzi-la.`,`só incide no transporte aéreo.`,`foi revogada pelo Pacote Anticrime.`,`incide apenas no tráfico interestadual.`],a:1,
x:`STF e STJ: a majorante pune a maior exposição de pessoas à droga; por isso, exige a comercialização dentro do transporte.`},

{c:'c13',b:'Vunesp',e:`O único crime culposo previsto na Lei nº 11.343/2006 consiste em`,
o:[`trazer consigo droga para consumo pessoal.`,`prescrever ou ministrar, culposamente, drogas, sem que delas necessite o paciente, ou fazê-lo em doses excessivas ou em desacordo com determinação legal ou regulamentar.`,`conduzir embarcação após o consumo de drogas.`,`induzir alguém ao uso indevido de droga.`,`oferecer droga a pessoa de seu relacionamento.`],a:1,
x:`Art. 38 (detenção de 6 meses a 2 anos e multa), crime próprio de profissionais de saúde.`},

{c:'c13',b:'FCC',e:`De acordo com o STF (RE 603.616, Tema 280), a entrada forçada em domicílio sem mandado judicial`,
o:[`é sempre ilícita no período noturno.`,`só é lícita, mesmo em período noturno, quando amparada em fundadas razões, devidamente justificadas a posteriori, que indiquem que dentro da casa ocorre situação de flagrante delito, sob pena de responsabilidade disciplinar, civil e penal do agente e de nulidade dos atos praticados.`,`é lícita sempre que se tratar de crime permanente, como o tráfico, independentemente de qualquer justificativa.`,`depende de autorização verbal do delegado de polícia.`,`é lícita com base exclusivamente em denúncia anônima.`],a:1,
x:`Tema 280 do STF. O STJ acrescenta que denúncia anônima, "atitude suspeita" ou fuga isolada não constituem fundadas razões, e que o consentimento do morador deve ser comprovado.`},

{c:'c13',b:'Vunesp',e:`O crime de tráfico de drogas (art. 33, caput, da Lei nº 11.343/2006) é punido com`,
o:[`reclusão, de 3 a 10 anos, e multa.`,`reclusão, de 5 a 15 anos, e pagamento de 500 a 1.500 dias-multa.`,`reclusão, de 8 a 20 anos.`,`detenção, de 1 a 3 anos.`,`reclusão, de 4 a 12 anos.`],a:1,
x:`Art. 33, caput. Tipo misto alternativo com 18 verbos; fornecer "ainda que gratuitamente" também é tráfico.`},

{c:'c13',b:'FCC',e:`Com o Pacote Anticrime, passou a incorrer nas penas do tráfico de drogas quem vende ou entrega drogas, sem autorização, a agente policial disfarçado,`,
o:[`em qualquer hipótese, ainda que o policial tenha induzido o agente à prática do crime.`,`quando presentes elementos probatórios razoáveis de conduta criminal preexistente.`,`somente se houver autorização judicial prévia.`,`somente se o agente for reincidente.`,`desde que a operação seja filmada.`],a:1,
x:`Art. 33, § 1º, IV. A exigência de conduta criminal preexistente distingue a figura do flagrante preparado (Súmula 145 STF), em que a polícia provoca o crime.`},

{c:'c13',b:'Vunesp',e:`Assinale a alternativa correta acerca do art. 44 da Lei de Drogas, à luz da jurisprudência do STF.`,
o:[`É constitucional a vedação abstrata de liberdade provisória para o tráfico.`,`Os crimes de tráfico são inafiançáveis e insuscetíveis de graça, indulto e anistia, mas o STF declarou inconstitucionais a vedação abstrata da liberdade provisória e a proibição de conversão da pena em restritiva de direitos.`,`O tráfico admite fiança arbitrada pelo delegado.`,`O livramento condicional no tráfico exige o cumprimento de 1/3 da pena.`,`O reincidente específico em tráfico pode obter livramento condicional após 2/3 da pena.`],a:1,
x:`STF: HC 104.339 (liberdade provisória) e HC 97.256 (conversão em restritivas; Resolução 5/2012 do Senado). O livramento exige 2/3 e é vedado ao reincidente específico (art. 44, parágrafo único).`},

/* ----- Drogas: bloco extra ----- */
{c:'c13',b:'Vunesp',e:`Quem, para seu consumo pessoal, semeia, cultiva ou colhe plantas destinadas à preparação de pequena quantidade de substância capaz de causar dependência física ou psíquica`,
o:[`comete tráfico de drogas por equiparação (art. 33, § 1º, II).`,`submete-se às mesmas medidas previstas para o porte para consumo pessoal (art. 28, § 1º).`,`comete crime punido com detenção de 1 a 3 anos.`,`pratica conduta sempre atípica.`,`comete crime ambiental.`],a:1,
x:`Art. 28, § 1º. O cultivo destinado ao tráfico é o art. 33, § 1º, II. Para a maconha, o STF (Tema 506) presume usuário quem cultiva até 6 plantas-fêmeas, e a conduta deixa de ter natureza penal.`},

{c:'c13',b:'FCC',e:`Para garantia do cumprimento das medidas educativas aplicadas ao usuário (art. 28), a que injustificadamente se recuse o agente, o juiz poderá submetê-lo, sucessivamente, a`,
o:[`prisão simples e multa.`,`admoestação verbal e multa.`,`advertência e internação compulsória.`,`detenção de até 6 meses e multa.`,`suspensão da CNH e multa.`],a:1,
x:`Art. 28, § 6º. Não há pena privativa de liberdade para o usuário em nenhuma hipótese.`},

{c:'c13',b:'Vunesp',e:`Prescrevem em ___ a imposição e a execução das penas aplicadas ao usuário de drogas (art. 28 da Lei nº 11.343/2006), observadas as causas interruptivas do Código Penal. Assinale a alternativa que preenche a lacuna.`,
o:[`1 ano`,`2 anos`,`3 anos`,`4 anos`,`5 anos`],a:1,
x:`Art. 30 da Lei 11.343/2006.`},

{c:'c13',b:'FCC',e:`O usuário de drogas (art. 28), salvo se houver concurso com os crimes dos arts. 33 a 37 da Lei nº 11.343/2006, será processado e julgado`,
o:[`pela Vara Criminal comum, pelo rito ordinário.`,`na forma da Lei nº 9.099/1995 (Juizado Especial Criminal), podendo o Ministério Público propor a aplicação imediata das penas do art. 28.`,`pela Vara da Infância e Juventude.`,`pelo Tribunal do Júri.`,`exclusivamente pela autoridade administrativa sanitária.`],a:1,
x:`Art. 48, §§ 1º e 5º. Para a maconha, o STF (Tema 506) determinou que as sanções sejam aplicadas em procedimento de natureza não penal, sem efeitos criminais.`},

{c:'c13',b:'Vunesp',e:`Após o julgamento do STF no RE 635.659 (Tema 506), a pessoa abordada por policiais militares trazendo consigo pequena porção de cocaína para consumo pessoal`,
o:[`não comete infração penal, pois o STF descriminalizou o porte de todas as drogas para consumo.`,`continua a praticar a conduta do art. 28, de natureza penal, não se impondo prisão em flagrante e lavrando-se termo circunstanciado.`,`deve ser presa em flagrante por tráfico, independentemente da quantidade.`,`só responde se portar mais de 40 gramas.`,`deve ser liberada sem apreensão da droga.`],a:1,
x:`A tese do Tema 506 vale só para a cannabis sativa. Para as demais drogas, o porte para consumo continua sendo crime do art. 28, sem prisão em flagrante (art. 48, § 2º).`},

{c:'c13',b:'FCC',e:`Induzir, instigar ou auxiliar alguém ao uso indevido de droga é crime previsto no art. 33, § 2º, da Lei de Drogas, punido com`,
o:[`reclusão, de 5 a 15 anos.`,`detenção, de 1 a 3 anos, e multa, não configurando o crime, segundo o STF, a realização de manifestações públicas em favor da legalização das drogas.`,`detenção, de 6 meses a 1 ano.`,`as penas do art. 28, apenas.`,`reclusão, de 2 a 6 anos.`],a:1,
x:`Art. 33, § 2º. O STF (ADI 4.274 e ADPF 187) deu interpretação conforme para excluir da tipificação a "Marcha da Maconha" e manifestações em defesa da legalização (liberdade de reunião e expressão).`},

{c:'c13',b:'Vunesp',e:`O proprietário de imóvel que consente que outrem dele se utilize, ainda que gratuitamente, para o tráfico ilícito de drogas`,
o:[`comete apenas infração administrativa.`,`incorre nas mesmas penas do tráfico (art. 33, § 1º, III).`,`comete o crime de favorecimento real.`,`pratica conduta atípica, se não receber vantagem.`,`responde apenas por associação para o tráfico.`],a:1,
x:`Art. 33, § 1º, III: utilizar local ou bem de que tem a propriedade, posse, administração, guarda ou vigilância, ou consentir que outrem dele se utilize, ainda que gratuitamente, para o tráfico.`},

{c:'c13',b:'FCC',e:`Fabricar, adquirir, utilizar, transportar, possuir ou guardar maquinário, aparelho, instrumento ou qualquer objeto destinado à fabricação, preparação, produção ou transformação de drogas é crime punido com`,
o:[`reclusão, de 3 a 10 anos, e pagamento de 1.200 a 2.000 dias-multa.`,`reclusão, de 5 a 15 anos.`,`detenção, de 1 a 3 anos.`,`reclusão, de 8 a 20 anos.`,`reclusão, de 2 a 6 anos.`],a:0,
x:`Art. 34 da Lei 11.343/2006. Está entre os crimes inafiançáveis do art. 44 e equiparados a hediondo.`},

{c:'c13',b:'Vunesp',e:`Segundo o STJ, o agente que financia ou custeia o tráfico e, ao mesmo tempo, pratica ele próprio o tráfico (autofinanciamento) responde`,
o:[`pelos crimes dos arts. 33 e 36, em concurso material.`,`pelo crime do art. 33, com a causa de aumento do art. 40, VII, e não pelo art. 36 em concurso.`,`apenas pelo art. 36, que absorve o tráfico.`,`pelo art. 35 (associação), apenas.`,`pelo art. 36, com a majorante do art. 40, VII.`],a:1,
x:`O art. 36 (reclusão de 8 a 20 anos) pune quem financia o tráfico alheio. Quem financia e também trafica responde pelo art. 33 com a majorante do art. 40, VII (financiar ou custear a prática do crime).`},

{c:'c13',b:'FCC',e:`Conduzir veículo automotor sob a influência de substância psicoativa que determine dependência configura`,
o:[`o crime do art. 39 da Lei de Drogas.`,`o crime do art. 306 do Código de Trânsito Brasileiro, pois o art. 39 da Lei de Drogas abrange apenas embarcação ou aeronave.`,`tráfico de drogas, se houver droga no veículo.`,`apenas infração administrativa de trânsito.`,`o crime do art. 28 da Lei de Drogas.`],a:1,
x:`Art. 39 da Lei 11.343/2006: conduzir embarcação ou aeronave após o consumo de drogas, expondo a dano potencial a incolumidade de outrem (detenção de 6 meses a 3 anos; de 4 a 6 anos se for transporte coletivo de passageiros).`},

{c:'c13',b:'Vunesp',e:`Segundo a jurisprudência do STJ, a causa de aumento do tráfico praticado nas imediações de estabelecimento de ensino (art. 40, III)`,
o:[`exige prova de que o agente vendia droga especificamente aos alunos.`,`tem natureza objetiva, bastando que o crime ocorra nas imediações do estabelecimento, sem necessidade de comprovar que o agente visava seus frequentadores.`,`só incide se o agente for professor da escola.`,`só incide no tráfico interestadual.`,`foi revogada pela Lei nº 13.964/2019.`],a:1,
x:`Para o STJ, a majorante das imediações de estabelecimentos (ensino, prisional, hospitalar, unidades policiais etc.) é objetiva. Situação diferente é a do transporte público, que exige a comercialização dentro do veículo.`},

{c:'c13',b:'FCC',e:`Um adulto pratica o tráfico de drogas valendo-se de um adolescente para fazer as entregas. Segundo o entendimento do STJ,`,
o:[`responde por tráfico e por corrupção de menores (art. 244-B do ECA), em concurso material.`,`responde por tráfico com a causa de aumento do art. 40, VI, da Lei de Drogas, e não também pelo art. 244-B do ECA, sob pena de bis in idem, por aplicação do princípio da especialidade.`,`responde apenas por corrupção de menores.`,`não responde por nenhuma majorante, pois o adolescente é inimputável.`,`responde por associação para o tráfico, necessariamente.`],a:1,
x:`Quando o adolescente é envolvido no próprio tráfico, a norma especial é a majorante do art. 40, VI (envolver ou visar criança ou adolescente). O art. 244-B do ECA fica para o envolvimento do menor em outros crimes.`},

{c:'c13',b:'Vunesp',e:`O tráfico de drogas com destino ao exterior (transnacional) é de competência`,
o:[`da Justiça Estadual, em qualquer caso.`,`da Justiça Federal, conforme a Súmula 522 do STF, sendo a regra geral a competência da Justiça Estadual para os crimes relativos a entorpecentes.`,`da Justiça Militar da União.`,`do Superior Tribunal de Justiça.`,`da Justiça Federal apenas se a droga ultrapassar a fronteira.`],a:1,
x:`Súmula 522 STF e art. 70 da Lei 11.343/2006. A majorante da transnacionalidade dispensa a efetiva transposição da fronteira (Súmula 607 STJ).`},

{c:'c13',b:'FCC',e:`O indiciado ou acusado que colaborar voluntariamente com a investigação policial e o processo criminal na identificação dos demais coautores ou partícipes do crime e na recuperação total ou parcial do produto do crime, no caso de condenação, terá a pena`,
o:[`reduzida de 1/6 a 1/3.`,`reduzida de 1/3 a 2/3.`,`extinta pelo perdão judicial, obrigatoriamente.`,`reduzida pela metade.`,`substituída por restritiva de direitos.`],a:1,
x:`Art. 41 da Lei 11.343/2006.`},

{c:'c13',b:'Vunesp',e:`Na fixação das penas dos crimes da Lei de Drogas, o juiz considerará, com preponderância sobre o previsto no art. 59 do Código Penal,`,
o:[`os antecedentes e o comportamento da vítima.`,`a natureza e a quantidade da substância ou do produto, a personalidade e a conduta social do agente.`,`a motivação e as consequências do crime, apenas.`,`a renda do agente e o valor da droga.`,`o local da apreensão e o horário do crime.`],a:1,
x:`Art. 42 da Lei 11.343/2006.`},

{c:'c13',b:'FCC',e:`Segundo o STF (Tema 712 da repercussão geral), na dosimetria da pena do tráfico, as circunstâncias da natureza e da quantidade da droga apreendida`,
o:[`devem ser consideradas na primeira e na terceira fases, cumulativamente.`,`devem ser levadas em consideração apenas em uma das fases do cálculo da pena, sob pena de bis in idem.`,`não podem ser consideradas em nenhuma fase.`,`só podem afastar o tráfico privilegiado.`,`só podem ser consideradas na segunda fase, como agravantes.`],a:1,
x:`Tema 712 (ARE 666.334): vedado usar a natureza e a quantidade da droga para aumentar a pena-base e, ao mesmo tempo, para negar ou modular a redução do tráfico privilegiado.`},

{c:'c13',b:'Vunesp',e:`Segundo o STJ (Tema 1.139), para afastar o tráfico privilegiado (art. 33, § 4º, da Lei de Drogas),`,
o:[`basta a existência de inquéritos policiais em andamento contra o réu.`,`é vedada a utilização de inquéritos e/ou ações penais em curso como fundamento para negar a redução de pena.`,`basta a existência de ação penal em curso por qualquer crime.`,`é suficiente a apreensão de qualquer quantidade de cocaína.`,`basta que o réu esteja desempregado.`],a:1,
x:`Tema 1.139 do STJ, em respeito à presunção de inocência. Os requisitos do § 4º são primariedade, bons antecedentes, não dedicação a atividades criminosas e não integração em organização criminosa.`},

{c:'c13',b:'FCC',e:`Nos termos do art. 45 da Lei de Drogas, é isento de pena o agente que, em razão da dependência, ou sob o efeito de droga proveniente de caso fortuito ou força maior, era, ao tempo da ação ou da omissão, qualquer que tenha sido a infração penal praticada,`,
o:[`parcialmente capaz de entender o caráter ilícito do fato, hipótese em que a pena será reduzida pela metade.`,`inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento, podendo o juiz, na sentença absolutória, determinar o encaminhamento para tratamento médico adequado.`,`maior de 70 anos.`,`reincidente em crimes da Lei de Drogas.`,`usuário eventual de qualquer droga.`],a:1,
x:`Art. 45 e parágrafo único. Se a capacidade era apenas reduzida (não plena), a pena pode ser reduzida de 1/3 a 2/3 (art. 46).`},

{c:'c13',b:'Vunesp',e:`Ocorrendo prisão em flagrante por tráfico de drogas, a autoridade de polícia judiciária fará imediata comunicação ao juiz competente, remetendo-lhe cópia do auto lavrado, do qual será dada vista ao órgão do Ministério Público em`,
o:[`12 horas.`,`24 horas.`,`48 horas.`,`72 horas.`,`5 dias.`],a:1,
x:`Art. 50, caput, da Lei 11.343/2006.`},

{c:'c13',b:'FCC',e:`Quanto à destruição das drogas apreendidas, a Lei nº 11.343/2006 prevê que`,
o:[`a destruição depende sempre do trânsito em julgado da sentença.`,`havendo flagrante, o juiz, em 10 dias, certificará a regularidade do laudo de constatação e determinará a destruição, executada pelo delegado em 15 dias, guardando-se amostra; sem flagrante, a destruição ocorre em até 30 dias da apreensão.`,`a droga deve ser guardada integralmente até o fim do processo.`,`a destruição é feita pelo policial militar responsável pela apreensão, no local.`,`a destruição só pode ocorrer após o laudo definitivo, em 90 dias.`],a:1,
x:`Art. 50, §§ 3º e 4º, e art. 50-A. A destruição do § 4º é feita na presença do MP e da autoridade sanitária.`},

{c:'c13',b:'Vunesp',e:`Na Lei de Drogas, a infiltração por agentes de polícia e a não atuação policial sobre os portadores de drogas, para identificar e responsabilizar maior número de integrantes da operação (ação controlada), dependem de`,
o:[`ordem do delegado-geral de polícia.`,`autorização judicial, ouvido o Ministério Público.`,`autorização do Comandante-Geral da Polícia Militar.`,`requisição do Ministro da Justiça.`,`nenhuma autorização, por se tratar de crime permanente.`],a:1,
x:`Art. 53, I e II. Na ação controlada, exige-se ainda que sejam conhecidos o itinerário provável e a identificação dos agentes do delito ou de colaboradores.`},

{c:'c13',b:'FCC',e:`Nos termos do art. 243 da Constituição Federal, as propriedades rurais e urbanas de qualquer região do País onde forem localizadas culturas ilegais de plantas psicotrópicas ou a exploração de trabalho escravo`,
o:[`serão desapropriadas mediante indenização em títulos da dívida agrária.`,`serão expropriadas e destinadas à reforma agrária e a programas de habitação popular, sem qualquer indenização ao proprietário e sem prejuízo de outras sanções previstas em lei.`,`serão confiscadas apenas se o proprietário for condenado por tráfico.`,`serão leiloadas, revertendo o valor à União.`,`ficarão sob intervenção federal por 5 anos.`],a:1,
x:`Art. 243, caput, da CF (redação da EC 81/2014). Todo bem de valor econômico apreendido em decorrência do tráfico também será confiscado e revertido a fundo especial (parágrafo único).`},

{c:'c13',b:'FCC',e:`<p>Considere as afirmações sobre a Lei de Drogas e a jurisprudência dos Tribunais Superiores:</p><ol type="I"><li>A associação para o tráfico (art. 35) exige estabilidade e permanência do vínculo entre os agentes.</li><li>Ações penais em curso podem ser utilizadas para afastar a causa de diminuição do tráfico privilegiado.</li><li>A associação para o tráfico é crime equiparado a hediondo.</li></ol><p>Está correto o que se afirma APENAS em</p>`,
o:[`I.`,`I e II.`,`II.`,`II e III.`,`I e III.`],a:0,
x:`I correta (STJ). II errada (Tema 1.139 do STJ). III errada: o STJ não considera a associação para o tráfico equiparada a hediondo, por não constar do art. 2º da Lei 8.072/90.`},

{c:'c13',b:'Vunesp',e:`<p>Considere as afirmações:</p><ol type="I"><li>O art. 39 da Lei de Drogas pune quem conduz veículo automotor após o consumo de drogas.</li><li>Prescrever ou ministrar culposamente drogas, sem que delas necessite o paciente, é crime previsto na Lei de Drogas.</li><li>Colaborar, como informante, com grupo destinado ao tráfico é crime punido com reclusão de 2 a 6 anos.</li></ol><p>Está correto o que se afirma APENAS em</p>`,
o:[`I.`,`I e II.`,`II e III.`,`III.`,`I e III.`],a:2,
x:`I errada: o art. 39 trata de embarcação ou aeronave; veículo automotor é o art. 306 do CTB. II correta (art. 38, único crime culposo da lei). III correta (art. 37).`},

/* ===== CAP 14 – ESTATUTO PMPE ===== */
{c:'c14',b:'Vunesp',e:`A Polícia Militar, assim como o Corpo de Bombeiros Militar, é instituição organizada com base`,
o:[`na eficiência e na publicidade.`,`na hierarquia e na disciplina.`,`na autonomia e na independência funcional.`,`na legalidade e na moralidade, apenas.`,`na rotatividade e na antiguidade.`],a:1,
x:`Art. 42, caput, CF, e Estatuto: hierarquia e disciplina são a base institucional da Polícia Militar.`},

{c:'c14',b:'FCC',e:`Segundo o Estatuto dos Policiais Militares, posto e graduação distinguem-se porque`,
o:[`posto é o grau hierárquico da praça, conferido pelo Comandante-Geral, e graduação é o grau do oficial, conferido pelo Governador.`,`posto é o grau hierárquico do oficial, conferido por ato do Governador do Estado, e graduação é o grau hierárquico da praça, conferido pelo Comandante-Geral.`,`ambos são conferidos pelo Secretário de Defesa Social.`,`posto refere-se à função exercida, e graduação, ao tempo de serviço.`,`posto é exclusivo dos coronéis, e graduação abrange os demais militares.`],a:1,
x:`Posto = oficial (ato do Governador; art. 42, § 1º, CF: patentes conferidas pelos governadores). Graduação = praça (ato do Comandante-Geral).`},

{c:'c14',b:'Vunesp',e:`Na escala hierárquica da Polícia Militar, o Aspirante-a-Oficial e o Aluno-Oficial (Cadete) integram o círculo de`,
o:[`oficiais subalternos.`,`oficiais intermediários.`,`praças especiais.`,`subtenentes e sargentos.`,`oficiais superiores.`],a:2,
x:`São praças especiais. Oficiais subalternos: 1º e 2º Tenentes; intermediário: Capitão; superiores: Major, Tenente-Coronel e Coronel.`},

{c:'c14',b:'FCC',e:`A situação na qual o policial militar da ativa deixa de ocupar vaga na escala hierárquica do seu Quadro, nela permanecendo sem número, denomina-se`,
o:[`reversão.`,`agregação.`,`reforma.`,`licenciamento.`,`exclusão.`],a:1,
x:`Agregação. Cessado o motivo, ocorre a reversão (retorno ao Quadro).`},

{c:'c14',b:'Vunesp',e:`O ato pelo qual o policial militar agregado retorna ao respectivo Quadro, tão logo cesse o motivo que determinou sua agregação, denomina-se`,
o:[`reintegração.`,`reversão.`,`readaptação.`,`recondução.`,`convocação.`],a:1,
x:`Reversão. Não confundir com a convocação, que alcança o militar da reserva remunerada.`},

{c:'c14',b:'FCC',e:`Nos termos da Constituição Federal, aplicável aos militares dos Estados,`,
o:[`são permitidas a sindicalização e a greve, desde que mantido o serviço mínimo.`,`são proibidas a sindicalização e a greve, e o militar, enquanto em serviço ativo, não pode estar filiado a partidos políticos.`,`é permitida a filiação partidária ao militar da ativa com mais de 10 anos de serviço.`,`é permitida a greve, mas vedada a sindicalização.`,`é vedado ao militar alistar-se como eleitor.`],a:1,
x:`Art. 142, § 3º, IV e V, c/c art. 42, § 1º, CF. O STF (ARE 654.432) estendeu a vedação de greve a todos os servidores que atuam diretamente na segurança pública.`},

{c:'c14',b:'Vunesp',e:`O militar alistável é elegível. Se contar mais de dez anos de serviço, nos termos do art. 14, § 8º, da Constituição Federal, ele`,
o:[`deverá afastar-se da atividade.`,`será agregado pela autoridade superior e, se eleito, passará automaticamente, no ato da diplomação, para a inatividade.`,`será demitido ex officio.`,`deverá filiar-se a partido um ano antes da eleição, permanecendo na ativa.`,`será transferido para a reserva no ato do registro da candidatura.`],a:1,
x:`Com menos de 10 anos: afasta-se da atividade. Com mais de 10 anos: é agregado e, se eleito, passa à inatividade na diplomação.`},

{c:'c14',b:'FCC',e:`Segundo a Súmula 673 do STF, o art. 125, § 4º, da Constituição Federal, que atribui ao tribunal competente decidir sobre a perda do posto e da patente dos oficiais e da graduação das praças,`,
o:[`impede qualquer exclusão de praça por via administrativa.`,`não impede a perda da graduação de militar mediante procedimento administrativo.`,`exige que a perda da graduação seja decidida pelo Superior Tribunal Militar.`,`só se aplica aos oficiais.`,`foi revogado pela EC 45/2004.`],a:1,
x:`Súmula 673 STF. Já a perda do posto e da patente do oficial depende de decisão do tribunal (em PE, o TJPE, por não haver Tribunal de Justiça Militar).`},

{c:'c14',b:'Vunesp',e:`De acordo com o Estatuto, ao policial militar da ativa é vedado comerciar ou tomar parte na administração ou gerência de sociedade, ou dela ser sócio ou participar,`,
o:[`sem qualquer exceção.`,`exceto como acionista ou quotista em sociedade anônima ou por quotas de responsabilidade limitada.`,`exceto se autorizado pelo Comandante da Unidade.`,`exceto durante as férias.`,`exceto se a sociedade não tiver fins lucrativos.`],a:1,
x:`Vedação típica do Estatuto: pode ser acionista ou quotista, mas não administrar ou gerir a sociedade.`},

{c:'c14',b:'FCC',e:`Quanto às situações de inatividade do policial militar, é correto afirmar que`,
o:[`o militar reformado pode ser convocado a qualquer tempo para o serviço ativo.`,`o militar da reserva remunerada fica sujeito à prestação de serviço na ativa, mediante convocação, enquanto o reformado é dispensado definitivamente da prestação de serviço.`,`reserva remunerada e reforma são sinônimos.`,`a reforma é sempre voluntária.`,`o militar da reserva não percebe remuneração.`],a:1,
x:`Reserva remunerada: inatividade com possibilidade de convocação. Reforma: inatividade definitiva.`},

{c:'c14',b:'Vunesp',e:`Na hierarquia da Polícia Militar, é oficial intermediário o`,
o:[`Major.`,`Capitão.`,`1º Tenente.`,`Subtenente.`,`Aspirante-a-Oficial.`],a:1,
x:`Único posto do círculo de oficiais intermediários: Capitão. Major integra os oficiais superiores; 1º Tenente, os subalternos; Subtenente é praça; Aspirante, praça especial.`},

{c:'c14',b:'FCC',e:`Acerca do habeas corpus e das punições disciplinares militares, é correto afirmar, segundo a Constituição Federal e a jurisprudência do STF, que`,
o:[`cabe habeas corpus para discutir o mérito de qualquer punição disciplinar militar.`,`não caberá habeas corpus em relação a punições disciplinares militares, mas o STF admite o exame dos pressupostos de legalidade da punição.`,`o habeas corpus é cabível contra a pena de perda de patente.`,`a punição disciplinar militar não pode ser objeto de nenhum controle judicial.`,`só cabe habeas corpus se a punição for aplicada a oficial.`],a:1,
x:`Art. 142, § 2º, CF. O STF admite HC para verificar hierarquia, poder disciplinar, ato ligado à função e pena suscetível de aplicação, sem entrar no mérito. Súmula 694 STF: não cabe HC contra a perda de patente ou exclusão.`},

/* ===== CAP 15 – PESSOA IDOSA ===== */
{c:'c15',b:'Vunesp',e:`O Estatuto da Pessoa Idosa (Lei nº 10.741/2003) é destinado a regular os direitos assegurados às pessoas com idade`,
o:[`superior a 60 anos.`,`igual ou superior a 60 anos.`,`igual ou superior a 65 anos.`,`superior a 65 anos.`,`igual ou superior a 70 anos.`],a:1,
x:`Art. 1º: igual ou superior a 60 anos. Gratuidade no transporte coletivo urbano: maiores de 65 (art. 39). Prioridade especial: maiores de 80 (art. 3º, § 2º).`},

{c:'c15',b:'FCC',e:`Os crimes definidos no Estatuto da Pessoa Idosa são de ação penal`,
o:[`pública condicionada à representação, aplicando-se as imunidades dos arts. 181 e 182 do Código Penal.`,`pública incondicionada, não se lhes aplicando os arts. 181 e 182 do Código Penal.`,`privada, quando praticados por familiares.`,`pública incondicionada, aplicando-se a escusa absolutória ao descendente.`,`pública condicionada à requisição do Ministério Público.`],a:1,
x:`Art. 95. Assim, o filho que se apropria da aposentadoria do pai idoso não se beneficia da imunidade dos crimes patrimoniais entre parentes.`},

{c:'c15',b:'Vunesp',e:`O art. 94 do Estatuto da Pessoa Idosa determina a aplicação do procedimento da Lei nº 9.099/1995 aos crimes nele previstos cuja pena máxima não ultrapasse 4 anos. Segundo o STF (ADI 3.096), esse dispositivo`,
o:[`permite a transação penal e a composição civil para todos esses crimes.`,`deve ser interpretado no sentido de aplicar apenas o procedimento sumaríssimo, para dar celeridade ao processo, sem os benefícios despenalizadores ao autor do fato.`,`foi declarado integralmente inconstitucional.`,`transformou esses crimes em infrações de menor potencial ofensivo.`,`aplica-se somente às contravenções penais.`],a:1,
x:`Interpretação conforme: o objetivo é proteger a vítima idosa com rapidez, não beneficiar o autor.`},

{c:'c15',b:'FCC',e:`Reter o cartão magnético de conta bancária relativa a benefícios, proventos ou pensão da pessoa idosa, bem como qualquer outro documento, com o objetivo de assegurar recebimento ou ressarcimento de dívida, configura crime punido com`,
o:[`detenção, de 6 meses a 2 anos, e multa.`,`reclusão, de 1 a 4 anos.`,`reclusão, de 2 a 5 anos.`,`multa, apenas.`,`detenção, de 1 a 3 anos.`],a:0,
x:`Art. 104 do Estatuto da Pessoa Idosa.`},

{c:'c15',b:'Vunesp',e:`Apropriar-se de ou desviar bens, proventos, pensão ou qualquer outro rendimento da pessoa idosa, dando-lhes aplicação diversa da de sua finalidade, é crime punido com`,
o:[`detenção, de 6 meses a 1 ano.`,`reclusão, de 1 a 4 anos, e multa.`,`reclusão, de 2 a 5 anos.`,`detenção, de 1 a 3 anos.`,`reclusão, de 4 a 8 anos.`],a:1,
x:`Art. 102. A coação para doar, contratar, testar ou outorgar procuração (art. 107) é punida com reclusão de 2 a 5 anos.`},

{c:'c15',b:'FCC',e:`Abandonar a pessoa idosa em hospitais, casas de saúde, entidades de longa permanência, ou congêneres, ou não prover suas necessidades básicas, quando obrigado por lei ou mandado, é crime punido com`,
o:[`detenção, de 6 meses a 3 anos, e multa.`,`reclusão, de 2 a 4 anos.`,`detenção, de 2 meses a 1 ano.`,`reclusão, de 1 a 3 anos.`,`multa, apenas.`],a:0,
x:`Art. 98 do Estatuto da Pessoa Idosa.`},

{c:'c15',b:'Vunesp',e:`Aos maiores de ___ fica assegurada a gratuidade dos transportes coletivos públicos urbanos e semiurbanos, exceto nos serviços seletivos e especiais, quando prestados paralelamente aos serviços regulares. Assinale a alternativa que preenche a lacuna.`,
o:[`60 anos`,`62 anos`,`65 anos`,`70 anos`,`80 anos`],a:2,
x:`Art. 39. Basta apresentar documento pessoal que comprove a idade. Para pessoas entre 60 e 65 anos, a gratuidade depende da legislação local. Reservam-se 10% dos assentos.`},

{c:'c15',b:'FCC',e:`Os casos de suspeita ou confirmação de violência praticada contra pessoas idosas serão objeto de notificação compulsória pelos serviços de saúde públicos e privados à autoridade sanitária, bem como serão obrigatoriamente comunicados por eles`,
o:[`apenas ao Conselho Tutelar.`,`à autoridade policial, ao Ministério Público e aos Conselhos Municipal, Estadual e Nacional da Pessoa Idosa.`,`somente à família da vítima.`,`à Defensoria Pública, exclusivamente.`,`ao Poder Judiciário, que decidirá sobre a comunicação à polícia.`],a:1,
x:`Art. 19 do Estatuto. O art. 6º impõe a todo cidadão o dever de comunicar qualquer violação de que tenha conhecimento.`},

{c:'c15',b:'Vunesp',e:`Entre as pessoas idosas, o Estatuto assegura prioridade especial aos maiores de`,
o:[`65 anos.`,`70 anos.`,`75 anos.`,`80 anos.`,`90 anos.`],a:3,
x:`Art. 3º, § 2º (Lei 13.466/2017): maiores de 80 anos têm suas necessidades atendidas preferencialmente em relação às demais pessoas idosas, inclusive na tramitação processual.`},

{c:'c15',b:'FCC',e:`No crime de discriminar pessoa idosa, impedindo ou dificultando seu acesso a operações bancárias, aos meios de transporte ou ao direito de contratar, por motivo de idade (art. 96 do Estatuto),`,
o:[`a negativa de crédito motivada por superendividamento da pessoa idosa também configura o crime.`,`não constitui crime a negativa de crédito motivada por superendividamento da pessoa idosa.`,`a pena é aumentada de metade se praticado por instituição financeira.`,`a ação penal é privada.`,`exige-se dolo de lucro.`],a:1,
x:`Art. 96, § 3º (Lei 14.181/2021). A pena aumenta de 1/3 se a vítima estiver sob os cuidados ou responsabilidade do agente (§ 2º).`},

{c:'c15',b:'Vunesp',e:`No crime de omissão de socorro à pessoa idosa (art. 97 do Estatuto), punido com detenção de 6 meses a 1 ano e multa, a pena é`,
o:[`aumentada de 1/3 se resulta lesão grave e duplicada se resulta morte.`,`aumentada de metade se da omissão resulta lesão corporal de natureza grave, e triplicada se resulta a morte.`,`duplicada em qualquer caso de resultado danoso.`,`substituída por reclusão de 4 a 12 anos se resulta morte.`,`aumentada de 2/3 se resulta morte.`],a:1,
x:`Art. 97, parágrafo único. Não confundir com o art. 99 (expor a perigo), cuja forma com morte tem pena de reclusão de 4 a 12 anos.`},

{c:'c15',b:'FCC',e:`Coagir, de qualquer modo, a pessoa idosa a doar, contratar, testar ou outorgar procuração é crime punido com`,
o:[`detenção, de 6 meses a 1 ano.`,`reclusão, de 1 a 4 anos.`,`reclusão, de 2 a 5 anos.`,`reclusão, de 2 a 4 anos.`,`detenção, de 1 a 3 anos.`],a:2,
x:`Art. 107 do Estatuto: a maior pena entre os crimes da lei. Induzir idoso sem discernimento a outorgar procuração (art. 106): reclusão de 2 a 4 anos.`},

{c:'c15',b:'Vunesp',e:`Exibir ou veicular, por qualquer meio de comunicação, informações ou imagens depreciativas ou injuriosas à pessoa idosa é crime punido com`,
o:[`detenção, de 1 a 3 anos, e multa.`,`reclusão, de 2 a 5 anos.`,`multa, apenas.`,`detenção, de 6 meses a 1 ano.`,`reclusão, de 1 a 4 anos.`],a:0,
x:`Art. 105 do Estatuto da Pessoa Idosa.`},

/* ===== CAP 16 – JUVENTUDE ===== */
{c:'c16',b:'Vunesp',e:`Para os efeitos do Estatuto da Juventude (Lei nº 12.852/2013), são consideradas jovens as pessoas com idade entre`,
o:[`12 e 18 anos.`,`15 e 24 anos.`,`15 e 29 anos.`,`18 e 29 anos.`,`16 e 30 anos.`],a:2,
x:`Art. 1º, § 1º: 15 a 29 anos.`},

{c:'c16',b:'FCC',e:`Aos adolescentes com idade entre 15 e 18 anos, nos termos do Estatuto da Juventude,`,
o:[`aplica-se exclusivamente o Estatuto da Juventude.`,`aplica-se o Estatuto da Criança e do Adolescente e, excepcionalmente, o Estatuto da Juventude, quando não conflitar com as normas de proteção integral do adolescente.`,`aplica-se o Estatuto da Juventude, e, subsidiariamente, o ECA.`,`não se aplica nenhum dos dois estatutos.`,`aplica-se o Código Civil.`],a:1,
x:`Art. 1º, § 2º. A regra é o ECA; o Estatuto da Juventude é excepcional e não pode contrariar a proteção integral.`},

{c:'c16',b:'Vunesp',e:`O Estatuto da Juventude tem como princípio a promoção da autonomia e emancipação dos jovens. Segundo a lei, essa emancipação refere-se`,
o:[`à antecipação da capacidade civil aos 16 anos.`,`à trajetória de inclusão, liberdade e participação do jovem na vida social, e não ao instituto da emancipação disciplinado pelo Código Civil.`,`à independência financeira dos jovens em relação aos pais.`,`à redução da maioridade penal.`,`à emancipação política, com direito de voto aos 15 anos.`],a:1,
x:`Art. 2º, parágrafo único.`},

{c:'c16',b:'FCC',e:`Entre as diretrizes das políticas de segurança pública voltadas para os jovens, previstas no art. 38 do Estatuto da Juventude, está a`,
o:[`redução da maioridade penal para 16 anos.`,`priorização de ações voltadas para os jovens em situação de risco, vulnerabilidade social e egressos do sistema penitenciário nacional.`,`criação de delegacias exclusivas para jovens de 18 a 29 anos.`,`ampliação do toque de recolher para menores de 21 anos.`,`militarização das escolas públicas.`],a:1,
x:`Art. 38, IV. Outras diretrizes: integração com as demais políticas de juventude; prevenção e enfrentamento da violência; estudos e estatísticas sobre violência contra jovens; acesso à Defensoria Pública; acesso dos jovens com deficiência à justiça.`},

{c:'c16',b:'Vunesp',e:`No sistema de transporte coletivo interestadual, o Estatuto da Juventude assegura aos jovens de baixa renda`,
o:[`a gratuidade em todas as viagens.`,`a reserva de 2 vagas gratuitas por veículo e de 2 vagas com desconto de 50%, no mínimo, no valor das passagens, a serem utilizadas após esgotadas as vagas gratuitas.`,`desconto de 50% em todas as passagens.`,`a reserva de 10% dos assentos.`,`1 vaga gratuita por veículo.`],a:1,
x:`Art. 32 do Estatuto da Juventude, operacionalizado pela Identidade Jovem (ID Jovem).`},

{c:'c16',b:'FCC',e:`Segundo o Estatuto da Juventude, os conselhos de juventude são órgãos`,
o:[`temporários e subordinados ao Poder Executivo.`,`permanentes e autônomos, não jurisdicionais, encarregados de tratar das políticas públicas de juventude e da garantia do exercício dos direitos do jovem.`,`jurisdicionais, competentes para aplicar medidas aos jovens infratores.`,`vinculados ao Conselho Tutelar.`,`consultivos do Poder Judiciário.`],a:1,
x:`Art. 45 do Estatuto da Juventude. Note a semelhança com a definição do Conselho Tutelar (art. 131 do ECA).`},

{c:'c16',b:'Vunesp',e:`NÃO é princípio previsto no art. 2º do Estatuto da Juventude:`,
o:[`a valorização e promoção da participação social e política, de forma direta e por meio de suas representações.`,`o reconhecimento do jovem como sujeito de direitos universais, geracionais e singulares.`,`a promoção da vida segura, da cultura da paz, da solidariedade e da não discriminação.`,`a precedência dos direitos dos jovens sobre os das demais gerações.`,`a valorização do diálogo e convívio do jovem com as demais gerações.`],a:3,
x:`O Estatuto valoriza o diálogo e convívio com as demais gerações; não estabelece precedência sobre elas. Os demais são princípios do art. 2º.`},

{c:'c16',b:'FCC',e:`Nos termos do art. 37 do Estatuto da Juventude, todos os jovens têm direito de viver em um ambiente`,
o:[`seguro, sem violência, com garantia da sua incolumidade física e mental, sendo-lhes asseguradas a igualdade de oportunidades e facilidades para seu aperfeiçoamento intelectual, cultural e social.`,`familiar, devendo o Estado custear sua moradia até os 29 anos.`,`rural ou urbano, à sua escolha, com transporte gratuito.`,`escolar integral até os 24 anos.`,`livre de qualquer fiscalização policial.`],a:0,
x:`Literalidade do art. 37 (Seção XI – Do Direito à Segurança Pública e ao Acesso à Justiça).`},

{c:'c16',b:'Vunesp',e:`O Estatuto da Juventude NÃO prevê, entre os direitos dos jovens, o direito`,
o:[`à segurança pública e ao acesso à justiça.`,`ao território e à mobilidade.`,`à sustentabilidade e ao meio ambiente.`,`à emancipação civil automática aos 16 anos.`,`à diversidade e à igualdade.`],a:3,
x:`O Estatuto enumera 11 direitos: cidadania e participação; educação; profissionalização, trabalho e renda; diversidade e igualdade; saúde; cultura; comunicação e liberdade de expressão; desporto e lazer; território e mobilidade; sustentabilidade e meio ambiente; segurança pública e acesso à justiça. A emancipação civil é matéria do Código Civil.`},

{c:'c16',b:'FCC',e:`Entre as diretrizes gerais das políticas públicas de juventude (art. 3º do Estatuto), inclui-se promover a integração internacional entre os jovens,`,
o:[`exclusivamente no âmbito do Mercosul.`,`preferencialmente no âmbito da América Latina e da África, e a cooperação internacional.`,`preferencialmente com os países da OCDE.`,`apenas mediante intercâmbio universitário.`,`preferencialmente com os países de língua inglesa.`],a:1,
x:`Diretriz do art. 3º do Estatuto da Juventude, ao lado da intersetorialidade das políticas e da atenção aos jovens de 18 a 29 anos privados de liberdade e egressos.`},

{c:'c16',b:'Vunesp',e:`Constitui diretriz das políticas de segurança pública voltadas para os jovens, segundo o Estatuto da Juventude, a promoção do acesso efetivo dos jovens`,
o:[`ao porte de arma de fogo.`,`à Defensoria Pública, considerando as especificidades da condição juvenil.`,`ao serviço militar voluntário aos 15 anos.`,`às academias de polícia sem concurso.`,`ao Conselho Tutelar.`],a:1,
x:`Art. 38, V, do Estatuto da Juventude.`},

/* ===== CAP 17 – SÚMULAS ===== */
{c:'c17',b:'FCC',e:`Segundo a Súmula Vinculante 11, só é lícito o uso de algemas em casos de`,
o:[`prisão por crime hediondo, independentemente de justificativa.`,`resistência e de fundado receio de fuga ou de perigo à integridade física própria ou alheia, por parte do preso ou de terceiros, justificada a excepcionalidade por escrito.`,`prisão em flagrante, em qualquer hipótese.`,`condução de presos do sexo masculino.`,`determinação do Comandante da operação.`],a:1,
x:`SV 11. A inobservância gera responsabilidade disciplinar, civil e penal do agente e nulidade da prisão ou do ato processual, sem prejuízo da responsabilidade civil do Estado.`},

{c:'c17',b:'Vunesp',e:`Nos termos da Súmula Vinculante 14, é direito do defensor, no interesse do representado, ter acesso amplo aos elementos de prova que,`,
o:[`ainda não documentados, estejam em fase de produção.`,`já documentados em procedimento investigatório realizado por órgão com competência de polícia judiciária, digam respeito ao exercício do direito de defesa.`,`constem de interceptação telefônica em andamento.`,`sejam considerados sigilosos pelo delegado.`,`estejam na posse do Ministério Público, apenas.`],a:1,
x:`SV 14. Diligências em andamento, ainda não documentadas, podem ser mantidas em sigilo. Negar acesso indevidamente pode configurar o crime do art. 32 da Lei de Abuso de Autoridade.`},

{c:'c17',b:'FCC',e:`De acordo com a Súmula 694 do STF,`,
o:[`cabe habeas corpus contra a imposição de pena de exclusão de militar.`,`não cabe habeas corpus contra a imposição da pena de exclusão de militar ou de perda de patente ou de função pública.`,`cabe mandado de segurança contra punição disciplinar, apenas.`,`a perda da patente depende de decisão do STF.`,`não cabe habeas corpus em favor de militares.`],a:1,
x:`Súmula 694 STF: essas sanções não afetam a liberdade de locomoção, logo não são impugnáveis por HC.`},

{c:'c17',b:'Vunesp',e:`Segundo a Súmula 630 do STJ, a incidência da atenuante da confissão espontânea no crime de tráfico ilícito de entorpecentes`,
o:[`é automática quando o réu admite a posse da droga.`,`exige o reconhecimento da traficância pelo acusado, não bastando a mera admissão da posse ou propriedade para uso próprio.`,`é vedada em qualquer hipótese.`,`só se aplica ao tráfico privilegiado.`,`depende de colaboração premiada.`],a:1,
x:`Súmula 630 do STJ.`},

{c:'c17',b:'FCC',e:`Um adolescente pratica ato infracional aos 17 anos e completa 18 anos durante o cumprimento da medida de liberdade assistida. Segundo a Súmula 605 do STJ,`,
o:[`a medida deve ser extinta imediatamente.`,`a superveniência da maioridade penal não interfere na aplicabilidade da medida em curso, enquanto não atingidos 21 anos.`,`a medida deve ser convertida em pena privativa de liberdade.`,`o jovem passa a ser processado pela Justiça comum.`,`a medida só pode ser mantida se for de internação.`],a:1,
x:`Súmula 605 STJ, aplicável inclusive à liberdade assistida.`},

{c:'c17',b:'Vunesp',e:`Segundo o STF (HC 208.240, 2024), a busca pessoal independente de mandado judicial`,
o:[`pode ser realizada com base na intuição do policial.`,`deve estar fundada em elementos indiciários objetivos de que a pessoa esteja na posse de arma proibida ou de objetos que constituam corpo de delito, não sendo lícita a realização da medida com base na raça, sexo, orientação sexual, cor da pele ou aparência física.`,`é sempre lícita em locais de alta criminalidade.`,`exige autorização do delegado de polícia.`,`só pode ser feita em pessoas com antecedentes criminais.`],a:1,
x:`Tese do STF no HC 208.240, em harmonia com o art. 244 do CPP (fundada suspeita). Combate ao perfilamento racial.`},

{c:'c17',b:'FCC',e:`Segundo a Súmula 647 do STJ, são imprescritíveis`,
o:[`os crimes de tortura praticados durante o regime militar.`,`as ações indenizatórias por danos morais e materiais decorrentes de atos de perseguição política com violação de direitos fundamentais ocorridos durante o regime militar.`,`todos os crimes contra a humanidade, inclusive no direito interno.`,`as ações penais relativas a crimes hediondos.`,`as ações de improbidade administrativa culposas.`],a:1,
x:`A súmula trata de ações cíveis indenizatórias, não de crimes. No plano penal, a tortura é prescritível segundo a CF.`},

{c:'c17',b:'Vunesp',e:`De acordo com a Súmula 588 do STJ, a prática de crime ou contravenção penal contra a mulher com violência ou grave ameaça no ambiente doméstico`,
o:[`impossibilita a substituição da pena privativa de liberdade por restritiva de direitos.`,`permite a substituição da pena por cesta básica.`,`autoriza a transação penal.`,`admite a aplicação do princípio da insignificância.`,`impõe a ação penal privada.`],a:0,
x:`Súmula 588 STJ.`},

{c:'c17',b:'FCC',e:`No julgamento do HC 82.424 (caso Ellwanger), em 2003, o STF decidiu que`,
o:[`o antissemitismo não configura racismo, pois judeus não constituem raça em sentido biológico.`,`a publicação de obras antissemitas configura racismo, crime imprescritível, por ser a raça um conceito social e não biológico.`,`a liberdade de expressão é absoluta e protege qualquer publicação.`,`o crime de racismo prescreve em 20 anos.`,`o racismo só se configura contra pessoas negras.`],a:1,
x:`Caso Ellwanger: marco do conceito social (político-cultural) de raça, base também da ADO 26 (homotransfobia).`},

{c:'c17',b:'Vunesp',e:`Segundo a Súmula Vinculante 56, a falta de estabelecimento penal adequado`,
o:[`autoriza a manutenção do condenado em regime prisional mais gravoso.`,`não autoriza a manutenção do condenado em regime prisional mais gravoso, devendo-se observar os parâmetros fixados no RE 641.320/RS.`,`impõe a soltura imediata de todos os presos.`,`autoriza a prisão domiciliar apenas para crimes culposos.`,`deve ser suprida com a transferência do preso para cadeia pública.`],a:1,
x:`SV 56. Parâmetros do RE 641.320: saída antecipada, liberdade eletronicamente monitorada, penas alternativas ou estudo para o sentenciado que progride.`}
);
